  ('2d7b313e-d1cf-5646-8d0a-02e9a43532bf', null, (select id from public.skills where slug = 'read-g5-connections'), null, 'hard',
   $q$Which statement best explains the relationship among otters, urchins, and kelp?$q$, $q$[{"text":"Urchins protect kelp by keeping otters away from the sea floor.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Otters and urchins work together to keep the kelp healthy.","is_correct":false,"misconception_token":"misreads-relationship"},{"text":"Kelp helps otters directly by giving them food to eat each day.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Otters help kelp indirectly by eating the animals that eat kelp.","is_correct":true}]$q$::jsonb, $q$Otters help kelp indirectly by eating the animals that eat kelp.$q$, $q$Otters never touch the kelp in the passage, yet they protect it by eating urchins, which are the animals that destroy kelp. Otters and urchins do not work together; otters eat urchins.$q$, 'draft', '422701ab-d591-5142-96ff-ff2840b1a888')
