  ('dc7f9568-9251-5086-966d-912684bf5f11', null, (select id from public.skills where slug = 'read-g5-figurative-language'), null, 'easy',
   $q$In paragraph 5, Dev tells Priya, "You were on fire!" What does this idiom mean?$q$, $q$[{"text":"She made a lot of mistakes.","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"She played extremely well.","is_correct":true},{"text":"She was too warm on stage.","is_correct":false,"misconception_token":"literal-reading"},{"text":"She played much too fast.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$She played extremely well.$q$, $q$Dev hugs her after the crowd bursts into applause, so he is praising her playing. Nothing in the story says she was hot or rushed.$q$, 'draft', '80aa67a6-66ba-5905-ac37-bf7cd62dc883')
