-- Passage rg5-main-idea-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('04d5bc7e-2780-5cfd-ade4-4fba108e590c', 'rg5-main-idea-summary-p06', (select id from public.skills where slug = 'read-g5-main-idea-summary'), null,
        '3-5', $q$Turning Sunlight into Power$q$, $q$On many rooftops today, you can see dark, flat panels tilted toward the sky. These are solar panels. They turn sunlight into electricity that can power lights, computers and refrigerators.

A solar panel is made of many small squares called cells. Each cell contains thin layers of a material called silicon. When sunlight hits a cell, it knocks tiny particles loose inside the silicon. Those moving particles create an electric current. Wires carry the current from the panel into the building.

Solar power has some big advantages. Sunlight is free, and it will not run out. Solar panels also make electricity without smoke or loud noise, so they keep the air cleaner than some other power sources.

Solar power has limits, too. Panels make no electricity at night and less on cloudy days. To solve this problem, some homes store extra power in large batteries during the day. Then they use the stored power after dark.

Engineers keep working to make solar cells cheaper and better at catching light. As the panels improve, more families and schools are choosing to use the sun to meet their energy needs.$q$, 'draft')
