-- Passage rg5-story-details-inference-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('1dcfe81c-403c-5bee-8af4-de272254b74a', 'rg5-story-details-inference-p04', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$The Chalk Mark$q$, $q$All week, Lena Kowalski and Darius Bell practiced the baton handoff for the relay race. Darius ran the second part of the race, and Lena ran the third. Coach Nwosu drew a chalk mark on the track. When Darius reached that mark, Lena was supposed to start running.

"Not before," Coach said. "If you leave too early, he will never catch you."

On the day of the meet, the stands were full of families waving signs. Lena's heart thumped as she watched Darius round the curve. He was flying. Before he reached the chalk mark, she spun and took off.

Behind her, she heard him shout her name. She looked back. He was still three steps behind, with his arm stretched out. Lena slowed almost to a jog until the baton slapped into her palm. Then she ran harder than she ever had.

Their team finished second, one step behind the runners from Maple Ridge.

Lena sat on the grass with her head down. Darius sat beside her and handed her a water bottle. "Monday," he said, "we practice the mark again. Fifty times."

Lena looked up. For the first time all afternoon, she almost smiled.$q$, 'draft')
